CREATE TABLE IF NOT EXISTS `admin_doc_permission` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键',
  `site` varchar(16) NOT NULL COMMENT '文档站：admin或api',
  `path` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT '文档站内相对路径',
  `title` varchar(100) NOT NULL DEFAULT '' COMMENT '文档标题',
  `description` varchar(255) NOT NULL DEFAULT '' COMMENT '描述',
  `status` tinyint unsigned NOT NULL DEFAULT '1' COMMENT '状态：1启用；0禁用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '修改时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_site_path` (`site`,`path`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='文档权限';

